insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (9, 1, 8, 9, true, 'AI-Assisted Test Generation', 'Using AI agents to generate test cases, identify edge cases, and triage failures. GitHub Copilot, Cursor, and custom test-generation pipelines.', 'https://free-tier-insights--amielpeled.replit.app/ai-testing-lecture-9/slide1?lang=en');
