insert into lecture_tracks (id, lang, position, title, lead) values (3, 'he', 0, 'בדיקות AI', 'מהיסודות של בדיקות AI ועד לטכניקות הערכה מתקדמות.');
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (21, 3, 0, 1, true, 'מבוא לבדיקות AI', 'מהן בדיקות AI, למה הן חשובות, וכיצד הן שונות מבדיקות תוכנה מסורתיות. מכסה LLMs, אי-דטרמיניזם, אסטרטגיות הערכה ונוף בדיקות ה-AI המודרני.', 'https://free-tier-insights--amielpeled.replit.app/ai-testing-lecture-1/slide1?lang=he');
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (22, 3, 1, 2, true, 'הנדסת Prompt לבודקים', 'כיצד לכתוב prompts שמייצרים תוצאות עקביות וניתנות לבדיקה. מכסה מבנה prompt, system messages, temperature ויסודות prompt injection.', 'https://free-tier-insights--amielpeled.replit.app/ai-testing-lecture-2/slide1?lang=he');
